"use client";

import {
  Background,
  BackgroundVariant,
  Controls,
  Handle,
  MiniMap,
  Position,
  ReactFlow,
  ReactFlowProvider,
  useReactFlow,
  type NodeProps,
} from "reactflow";

import type { WorkflowNodeData } from "@/app/lib/types";
import { useWorkflowStore } from "@/app/store/workflowStore";

const NODE_MIME = "application/x-forgeflow-node";
const TEMPLATE_MIME = "application/x-forgeflow-template";

function BlueprintNode({
  data,
  selected,
}: NodeProps<WorkflowNodeData>) {
  const chips = Object.entries(data.config).slice(0, 2);

  return (
    <div
      className={`relative min-w-[220px] rounded-[24px] border bg-white p-4 shadow-[0_18px_40px_rgba(15,23,42,0.08)] transition ${
        selected ? "border-sky-400 ring-4 ring-sky-100" : "border-slate-200"
      }`}
    >
      <Handle
        type="target"
        position={Position.Left}
        className="!h-3 !w-3 !border-2 !border-white !bg-slate-400"
      />
      <Handle
        type="source"
        position={Position.Right}
        className="!h-3 !w-3 !border-2 !border-white !bg-slate-400"
      />

      <div className="flex items-start gap-3">
        <div
          className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl text-xs font-bold text-white"
          style={{ backgroundColor: data.accent }}
        >
          {data.icon}
        </div>
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <p className="text-sm font-semibold text-slate-900">{data.label}</p>
            <span className="rounded-full bg-slate-100 px-2 py-1 text-[10px] font-semibold uppercase tracking-[0.16em] text-slate-500">
              {data.status}
            </span>
          </div>
          <p className="text-xs font-semibold uppercase tracking-[0.18em] text-slate-500">
            {data.subtitle}
          </p>
        </div>
      </div>

      <p className="mt-4 text-xs leading-5 text-slate-500">{data.description}</p>

      <div className="mt-4 flex flex-wrap gap-2">
        {chips.map(([key, value]) => (
          <span
            key={key}
            className="rounded-full bg-slate-100 px-2.5 py-1 text-[11px] font-medium text-slate-600"
          >
            {key}: {value}
          </span>
        ))}
      </div>
    </div>
  );
}

const nodeTypes = {
  blueprint: BlueprintNode,
};

function FlowCanvasInner() {
  const nodes = useWorkflowStore((state) => state.nodes);
  const edges = useWorkflowStore((state) => state.edges);
  const viewport = useWorkflowStore((state) => state.viewport);
  const onNodesChange = useWorkflowStore((state) => state.onNodesChange);
  const onEdgesChange = useWorkflowStore((state) => state.onEdgesChange);
  const onSelectionChange = useWorkflowStore((state) => state.onSelectionChange);
  const connect = useWorkflowStore((state) => state.connect);
  const addNode = useWorkflowStore((state) => state.addNode);
  const addTemplate = useWorkflowStore((state) => state.addTemplate);
  const setViewport = useWorkflowStore((state) => state.setViewport);
  const captureHistory = useWorkflowStore((state) => state.captureHistory);
  const { screenToFlowPosition } = useReactFlow();

  return (
    <div className="relative h-full min-h-[560px] rounded-[28px] border border-slate-200 bg-[radial-gradient(circle_at_top,_rgba(56,189,248,0.12),_transparent_32%),linear-gradient(180deg,#ffffff_0%,#f8fafc_100%)] shadow-[0_18px_50px_rgba(15,23,42,0.08)]">
      <div className="pointer-events-none absolute right-4 top-4 z-10 rounded-2xl border border-white/50 bg-white/75 px-4 py-3 text-xs text-slate-500 shadow-sm backdrop-blur">
        Drop nodes or templates anywhere. Grid snapping is on.
      </div>

      <ReactFlow
        nodes={nodes}
        edges={edges}
        nodeTypes={nodeTypes}
        defaultViewport={viewport}
        snapToGrid
        snapGrid={[24, 24]}
        minZoom={0.4}
        maxZoom={1.5}
        deleteKeyCode={null}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        onSelectionChange={onSelectionChange}
        onNodeDragStart={() => captureHistory()}
        onSelectionDragStart={() => captureHistory()}
        onMoveEnd={(_, nextViewport) => setViewport(nextViewport)}
        onConnect={connect}
        onPaneClick={() => onSelectionChange({ nodes: [], edges: [] })}
        isValidConnection={({ source, target }) => Boolean(source && target && source !== target)}
        onDragOver={(event) => {
          event.preventDefault();
          event.dataTransfer.dropEffect = "move";
        }}
        onDrop={(event) => {
          event.preventDefault();

          const nodePayload = event.dataTransfer.getData(NODE_MIME);
          const templatePayload = event.dataTransfer.getData(TEMPLATE_MIME);
          const position = screenToFlowPosition({
            x: event.clientX,
            y: event.clientY,
          });

          if (templatePayload) {
            const parsed = JSON.parse(templatePayload) as { templateId: string };
            addTemplate(parsed.templateId, position);
            return;
          }

          if (nodePayload) {
            const parsed = JSON.parse(nodePayload) as {
              kind: Parameters<typeof addNode>[0];
            };
            addNode(parsed.kind, position);
          }
        }}
      >
        <MiniMap
          pannable
          zoomable
          nodeBorderRadius={16}
          nodeColor={(node) => node.data?.accent || "#0f172a"}
          className="!bg-white/90 !shadow-lg"
        />
        <Controls className="!rounded-2xl !border !border-slate-200 !bg-white !shadow-md" />
        <Background
          variant={BackgroundVariant.Lines}
          gap={24}
          size={1}
          color="#d9e2ec"
        />
      </ReactFlow>
    </div>
  );
}

export default function FlowCanvas() {
  return (
    <ReactFlowProvider>
      <FlowCanvasInner />
    </ReactFlowProvider>
  );
}
