"use client";

import { NODE_LIBRARY } from "@/app/lib/workflow";

const NODE_MIME = "application/x-forgeflow-node";

export default function DraggableNodePanel() {
  return (
    <section className="space-y-3">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-sm font-semibold text-slate-900">Component library</h2>
          <p className="text-xs text-slate-500">
            Drag cards onto the grid to compose your workflow.
          </p>
        </div>
        <span className="rounded-full bg-slate-100 px-2 py-1 text-[11px] font-medium text-slate-500">
          {NODE_LIBRARY.length} nodes
        </span>
      </div>

      <div className="space-y-2">
        {NODE_LIBRARY.map((item) => (
          <button
            key={item.kind}
            type="button"
            draggable
            onDragStart={(event) => {
              const payload = JSON.stringify({ kind: item.kind });
              event.dataTransfer.effectAllowed = "move";
              event.dataTransfer.setData(NODE_MIME, payload);
              event.dataTransfer.setData("text/plain", payload);
            }}
            className="flex w-full items-start gap-3 rounded-2xl border border-slate-200 bg-white px-4 py-3 text-left shadow-sm transition hover:-translate-y-0.5 hover:border-slate-300 hover:shadow-md"
          >
            <span
              className="mt-0.5 flex h-10 w-10 shrink-0 items-center justify-center rounded-2xl text-xs font-bold text-white shadow-sm"
              style={{ backgroundColor: item.accent }}
            >
              {item.icon}
            </span>
            <span className="space-y-1">
              <span className="block text-sm font-semibold text-slate-900">
                {item.label}
              </span>
              <span className="block text-xs leading-5 text-slate-500">
                {item.blurb}
              </span>
            </span>
          </button>
        ))}
      </div>
    </section>
  );
}
