"use client";

import {
  addEdge,
  applyEdgeChanges,
  applyNodeChanges,
  MarkerType,
  type Connection,
  type EdgeChange,
  type NodeChange,
  type XYPosition,
} from "reactflow";
import { create } from "zustand";

import type {
  WorkflowDocument,
  WorkflowEdge,
  WorkflowNode,
  WorkflowNodeData,
  WorkflowTemplate,
  WorkflowViewport,
  WorkflowNodeKind,
} from "@/app/lib/types";
import {
  createDefaultFlow,
  createWorkflowNode,
  getTemplate,
  instantiateTemplate,
} from "@/app/lib/workflow";

type FlowSnapshot = {
  name: string;
  nodes: WorkflowNode[];
  edges: WorkflowEdge[];
  viewport: WorkflowViewport;
};

type WorkflowStore = {
  name: string;
  nodes: WorkflowNode[];
  edges: WorkflowEdge[];
  viewport: WorkflowViewport;
  selectedNodeId: string | null;
  selectedEdgeId: string | null;
  hydrated: boolean;
  history: FlowSnapshot[];
  future: FlowSnapshot[];
  initialize: (document: WorkflowDocument) => void;
  onNodesChange: (changes: NodeChange[]) => void;
  onEdgesChange: (changes: EdgeChange[]) => void;
  onSelectionChange: (selection: {
    nodes?: WorkflowNode[];
    edges?: WorkflowEdge[];
  }) => void;
  setViewport: (viewport: WorkflowViewport) => void;
  captureHistory: () => void;
  addNode: (kind: WorkflowNodeKind, position: XYPosition) => void;
  addTemplate: (templateId: string, position: XYPosition) => WorkflowTemplate | null;
  connect: (connection: Connection) => void;
  updateNodeData: (nodeId: string, next: Partial<WorkflowNodeData>) => void;
  replaceNodeData: (nodeId: string, next: WorkflowNodeData) => void;
  deleteSelection: () => void;
  undo: () => void;
  redo: () => void;
  exportDocument: (mode: WorkflowDocument["saveMode"]) => WorkflowDocument;
};

const seedDocument = createDefaultFlow();

function cloneSnapshot(snapshot: FlowSnapshot): FlowSnapshot {
  return structuredClone(snapshot);
}

function currentSnapshot(state: Pick<WorkflowStore, "name" | "nodes" | "edges" | "viewport">) {
  return cloneSnapshot({
    name: state.name,
    nodes: state.nodes,
    edges: state.edges,
    viewport: state.viewport,
  });
}

function withHistory(state: WorkflowStore) {
  const snapshot = currentSnapshot(state);
  return {
    history: [...state.history.slice(-29), snapshot],
    future: [],
  };
}

export const useWorkflowStore = create<WorkflowStore>((set, get) => ({
  name: seedDocument.name,
  nodes: seedDocument.nodes,
  edges: seedDocument.edges,
  viewport: seedDocument.viewport,
  selectedNodeId: null,
  selectedEdgeId: null,
  hydrated: false,
  history: [],
  future: [],
  initialize: (document) => {
    set({
      name: document.name,
      nodes: structuredClone(document.nodes),
      edges: structuredClone(document.edges),
      viewport: structuredClone(document.viewport),
      selectedNodeId: null,
      selectedEdgeId: null,
      hydrated: true,
      history: [],
      future: [],
    });
  },
  onNodesChange: (changes) => {
    set((state) => ({
      nodes: applyNodeChanges(changes, state.nodes),
    }));
  },
  onEdgesChange: (changes) => {
    set((state) => ({
      edges: applyEdgeChanges(changes, state.edges),
    }));
  },
  onSelectionChange: ({ nodes = [], edges = [] }) => {
    set({
      selectedNodeId: nodes[0]?.id ?? null,
      selectedEdgeId: edges[0]?.id ?? null,
    });
  },
  setViewport: (viewport) => {
    set({ viewport });
  },
  captureHistory: () => {
    set((state) => withHistory(state));
  },
  addNode: (kind, position) => {
    set((state) => ({
      ...withHistory(state),
      nodes: [...state.nodes, createWorkflowNode(kind, position)],
      selectedNodeId: null,
      selectedEdgeId: null,
    }));
  },
  addTemplate: (templateId, position) => {
    const template = getTemplate(templateId);

    if (!template) {
      return null;
    }

    const { nodes, edges } = instantiateTemplate(templateId, position);

    set((state) => ({
      ...withHistory(state),
      nodes: [...state.nodes, ...nodes],
      edges: [...state.edges, ...edges],
      selectedNodeId: null,
      selectedEdgeId: null,
    }));

    return template;
  },
  connect: (connection) => {
    set((state) => ({
      ...withHistory(state),
      edges: addEdge(
        {
          ...connection,
          animated: false,
          type: "smoothstep",
          markerEnd: { type: MarkerType.ArrowClosed },
        },
        state.edges,
      ),
    }));
  },
  updateNodeData: (nodeId, next) => {
    set((state) => ({
      ...withHistory(state),
      nodes: state.nodes.map((node) =>
        node.id === nodeId
          ? {
              ...node,
              data: {
                ...node.data,
                ...next,
                config: {
                  ...node.data.config,
                  ...next.config,
                },
              },
            }
          : node,
      ),
    }));
  },
  replaceNodeData: (nodeId, next) => {
    set((state) => ({
      ...withHistory(state),
      nodes: state.nodes.map((node) =>
        node.id === nodeId
          ? {
              ...node,
              data: next,
            }
          : node,
      ),
    }));
  },
  deleteSelection: () => {
    set((state) => {
      if (!state.selectedNodeId && !state.selectedEdgeId) {
        return state;
      }

      if (state.selectedNodeId) {
        return {
          ...withHistory(state),
          nodes: state.nodes.filter((node) => node.id !== state.selectedNodeId),
          edges: state.edges.filter(
            (edge) =>
              edge.source !== state.selectedNodeId &&
              edge.target !== state.selectedNodeId,
          ),
          selectedNodeId: null,
        };
      }

      return {
        ...withHistory(state),
        edges: state.edges.filter((edge) => edge.id !== state.selectedEdgeId),
        selectedEdgeId: null,
      };
    });
  },
  undo: () => {
    set((state) => {
      const previous = state.history.at(-1);

      if (!previous) {
        return state;
      }

      const current = currentSnapshot(state);

      return {
        ...cloneSnapshot(previous),
        selectedNodeId: null,
        selectedEdgeId: null,
        history: state.history.slice(0, -1),
        future: [current, ...state.future.slice(0, 29)],
      };
    });
  },
  redo: () => {
    set((state) => {
      const [next, ...rest] = state.future;

      if (!next) {
        return state;
      }

      const current = currentSnapshot(state);

      return {
        ...cloneSnapshot(next),
        selectedNodeId: null,
        selectedEdgeId: null,
        history: [...state.history.slice(-29), current],
        future: rest,
      };
    });
  },
  exportDocument: (mode) => {
    const state = get();

    return {
      name: state.name,
      nodes: structuredClone(state.nodes),
      edges: structuredClone(state.edges),
      viewport: structuredClone(state.viewport),
      updatedAt: new Date().toISOString(),
      saveMode: mode,
    };
  },
}));
